package glitch

import data.glitch_lib

# Define weak encryption indicators for CWE-326
weak_algorithms := {"DES", "3DES", "RC4", "AES-128", "Blowfish", "IDEA", "RSA-1024"}
weak_protocols := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1"}
weak_hashes := {"MD5", "SHA-1", "SHA1"}
weak_cipher_patterns := {"*CBC*", "*RC4*", "*DES*", "*MD5*", "*SHA1*", "NULL", "EXPORT", "anon"}

# Check if string value matches weak patterns
check_weak_string(value) {
    value.ir_type == "String"
    regex.match("(?i)(DES|3DES|RC4|AES-128|Blowfish|IDEA|RSA-1024|SSLv2|SSLv3|TLS[ _]?1\\.0|TLS[ _]?1\\.1|MD5|SHA-?1|CBC|NULL|EXPORT|anon)", value.value)
}

# Check if key length is insufficient
check_weak_key_length(value) {
    value.ir_type == "Integer"
    value.value < 256  # For symmetric encryption
} else {
    value.ir_type == "String"
    regex.match("(?i)key_?(size|length)\\s*[:=]\\s*(1024|192|128)", value.value)
}

# Main detection rule for weak encryption algorithms
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for algorithm or encryption attributes
    attr.name in {"algorithm", "encryption", "cipher_suite", "hash_algorithm", "signature_algorithm", "protocol", "tls_policy"}
    check_weak_string(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithms, protocols, or key sizes detected (CWE-326)"
    }
